17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Locale;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
107	            return new ResponseEntity<>(HttpStatus.CONFLICT);
108	        }
109	        this.clinicService.saveOwner(owner);
110	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
111	        headers.setLocation(UriComponentsBuilder.newInstance()
112	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
113	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
119	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
120	        if (currentOwner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        currentOwner.setAddress(ownerFieldsDto.getAddress());
124	        currentOwner.setCity(ownerFieldsDto.getCity());
125	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
126	        currentOwner.setLastName(ownerFieldsDto.getLastName());
127	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
128	        this.clinicService.saveOwner(currentOwner);
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Transactional
134	    @Override
135	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        this.clinicService.deleteOwner(owner);
141	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        HttpHeaders headers = new HttpHeaders();
152	        Pet pet = petMapper.toPet(petFieldsDto);
153	        owner.setId(ownerId);
154	        pet.setOwner(owner);
155	        pet.getType().setName(null);
156	        this.clinicService.savePet(pet);
157	        PetDto petDto = petMapper.toPetDto(pet);
158	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
159	            .buildAndExpand(pet.getId()).toUri());
160	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner != null) {
168	            Pet currentPet = this.clinicService.findPetById(petId);
169	            if (currentPet != null) {
170	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
171	                currentPet.setName(petFieldsDto.getName());
172	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
173	                this.clinicService.savePet(currentPet);
174	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	            }
176	        }
177	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
183	        HttpHeaders headers = new HttpHeaders();
184	        Visit visit = visitMapper.toVisit(visitFieldsDto);
185	        Pet pet = new Pet();
186	        pet.setId(petId);
187	        visit.setPet(pet);
188	        this.clinicService.saveVisit(visit);
189	        VisitDto visitDto = visitMapper.toVisitDto(visit);
190	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
191	            .buildAndExpand(visit.getId()).toUri());
192	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
193	    }
194	
195	
196	    /**
197	     * Determines whether the given telephone number is already used by any other owner.
198	     *
199	     * @param owner the candidate owner
200	     * @return {@code true} if an owner with the same telephone number already exists in the data store
201	     */
202	    private boolean isDuplicateOwner(Owner owner) {
203	        return this.clinicService.findAllOwners().stream()
204	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
205	    }
206	
207	    /**
208	     * Determines whether the given email address is already used by any other owner. An owner
209	     * without an email address is never considered a duplicate on this criterion. Email addresses
210	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
211	     * surrounding or repeated whitespace.
212	     *
213	     * @param owner the candidate owner
214	     * @return {@code true} if the owner provides an email already used by an existing owner
215	     */
216	    private boolean isDuplicateEmail(Owner owner) {
217	        String email = normalize(owner.getEmail());
218	        if (email.isEmpty()) {
219	            return false;
220	        }
221	        return this.clinicService.findAllOwners().stream()
222	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
223	    }
224	
225	    /**
226	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
227	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
228	     * collapsed to a single space and the result is lower-cased. This is what makes
229	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
230	     * duplicates. A {@code null} value normalizes to the empty string.
231	     *
232	     * @param value the raw value, may be {@code null}
233	     * @return the normalized value, never {@code null}
234	     */
235	    private static String normalize(String value) {
236	        if (value == null) {
237	            return "";
238	        }
239	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
245	        Owner owner = this.clinicService.findOwnerById(ownerId);
246	        if (owner != null) {
247	            Pet pet = owner.getPet(petId);
248	            if (pet != null) {
249	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
250	            }
251	        }
252	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	    }
254	}
