16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Digits(fraction = 0, integer = 10)
49	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
56	    private Set<Pet> pets;
57	
58	    public String getAddress() {
59	        return this.address;
60	    }
61	
62	    public void setAddress(String address) {
63	        this.address = address;
64	    }
65	
66	    public String getCity() {
67	        return this.city;
68	    }
69	
70	    public void setCity(String city) {
71	        this.city = city;
72	    }
73	
74	    public String getTelephone() {
75	        return this.telephone;
76	    }
77	
78	    public void setTelephone(String telephone) {
79	        this.telephone = telephone;
80	    }
81	
82	    public String getEmail() {
83	        return this.email;
84	    }
85	
86	    public void setEmail(String email) {
87	        this.email = email;
88	    }
89	
90	    protected Set<Pet> getPetsInternal() {
91	        if (this.pets == null) {
92	            this.pets = new HashSet<>();
93	        }
94	        return this.pets;
95	    }
96	
97	    protected void setPetsInternal(Set<Pet> pets) {
98	        this.pets = pets;
99	    }
100	
101	    public List<Pet> getPets() {
102	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
103	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
104	        return Collections.unmodifiableList(sortedPets);
105	    }
106	
107	    public void setPets(List<Pet> pets) {
108	        this.pets = new HashSet<>(pets);
109	    }
110	
111	    public void addPet(Pet pet) {
112	        getPetsInternal().add(pet);
113	        pet.setOwner(this);
114	    }
115	
116	    /**
117	     * Return the Pet with the given name, or null if none found for this Owner.
118	     *
119	     * @param name to test
120	     * @return true if pet name is already in use
121	     */
122	    public Pet getPet(String name) {
123	        return getPet(name, false);
124	    }
125	
126	    /**
127	     * Return the Pet with the given name, or null if none found for this Owner.
128	     *
129	     * @param name to test
130	     * @return true if pet name is already in use
131	     */
132	    public Pet getPet(String name, boolean ignoreNew) {
133	        name = name.toLowerCase();
134	        for (Pet pet : getPetsInternal()) {
135	            if (!ignoreNew || !pet.isNew()) {
136	                String compName = pet.getName();
137	                compName = compName.toLowerCase();
138	                if (compName.equals(name)) {
139	                    return pet;
140	                }
141	            }
142	        }
143	        return null;
144	    }
145	
146	    public Pet getPet(Integer petId) {
147	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
148	    }
149	
150	    @Override
151	    public String toString() {
152	        return new ToStringCreator(this)
153	
154	            .append("id", this.getId())
155	            .append("new", this.isNew())
156	            .append("lastName", this.getLastName())
157	            .append("firstName", this.getFirstName())
158	            .append("address", this.address)
159	            .append("city", this.city)
160	            .append("telephone", this.telephone)
161	            .toString();
162	    }
163	}
